import csv, json
from datetime import date

AUDIT_DATE = date(2026, 3, 31)
errors = []

# --- Re-run audit independently from source (compact) ---
register = {}
with open('/app/input/licensed_property_register.csv') as f:
    for row in csv.DictReader(f):
        register[row['license_id']] = row
superseded_by = {row['supersedes']: lid for lid, row in register.items() if row['supersedes'] != 'none'}

def terms(lic_id):
    if lic_id == 'none' or not lic_id: return None
    if lic_id not in register: return None
    r = register[lic_id]
    if lic_id in superseded_by:
        r = register[superseded_by[lic_id]]
    return r['license_type'], r['covers_distribution'], r['valid_until']

def covers(lic_id, use, dist):
    t = terms(lic_id)
    if t is None: return False
    lt, cd, vu = t
    if lt != use: return False
    if not (cd == 'all' or dist in [c.strip() for c in cd.split(';')]): return False
    if date.fromisoformat(vu) < AUDIT_DATE: return False
    return True

accounts = {}
with open('/app/input/client_accounts.csv') as f:
    for row in csv.DictReader(f):
        accounts[row['account_id']] = row
def clears(acc_id, dist):
    a = accounts[acc_id]
    if a['agreement_status'] != 'active': return False
    return dist in [c.strip() for c in a['master_agreement_covers'].split(';')] if a['master_agreement_covers'] != 'none' else False

reqs = []
with open('/app/input/composite_request_log.csv') as f:
    for row in csv.DictReader(f):
        reqs.append(row)
audited = [r for r in reqs if r['intake_status'] != 'withdrawn']
PP = {'social_public','print_for_sale'}
B = lambda s: s == 'True'
expected_audit = {}
fcodes = {k:0 for k in ['UNLICENSED_CHARACTER_USE','THIRD_PARTY_BACKGROUND_UNLICENSED','MISSING_MINOR_CONSENT','COMMERCIAL_DISTRIBUTION_FLAG','ALTERATION_DISCLOSURE_MISSING']}
ftotal = 0
flagged = 0
for r in audited:
    f = []; d = r['intended_distribution']
    if r['character_property'] != 'none':
        if not (d == 'personal_only' or covers(r['character_license_id'],'character',d)):
            f.append('UNLICENSED_CHARACTER_USE')
    if r['background_source'] == 'third_party_unlicensed':
        f.append('THIRD_PARTY_BACKGROUND_UNLICENSED')
    elif r['background_source'] == 'third_party_licensed' and not covers(r['background_license_id'],'background',d):
        f.append('THIRD_PARTY_BACKGROUND_UNLICENSED')
    if B(r['subject_is_minor']):
        ct = r['minor_consent_type']; bad = False
        if ct == 'none': bad = True
        else:
            if date.fromisoformat(r['minor_consent_valid_until']) < AUDIT_DATE: bad = True
            elif ct == 'basic' and d not in ('personal_only','client_internal'): bad = True
        if bad: f.append('MISSING_MINOR_CONSENT')
    if d in PP and not clears(r['account_id'], d):
        f.append('COMMERCIAL_DISTRIBUTION_FLAG')
    if r['alteration_level'] == 'substantive' and d in PP and not B(r['alteration_disclosure_on_file']):
        f.append('ALTERATION_DISCLOSURE_MISSING')
    expected_audit[r['request_id']] = sorted(f)
    if f:
        flagged += 1; ftotal += len(f)
        for c in f: fcodes[c]+=1

# expected account rollup
from collections import defaultdict
acc_reqs = defaultdict(list)
for r in audited: acc_reqs[r['account_id']].append(r)
batch_share = flagged/len(audited)
expected_acc = {}
for aid, a in accounts.items():
    rs = acc_reqs.get(aid,[])
    fc = sum(1 for r in rs if expected_audit[r['request_id']])
    sh = fc/len(rs) if rs else 0
    mx = max((len(expected_audit[r['request_id']]) for r in rs), default=0)
    exp = 'ESCALATION_REQUIRED' if (sh > batch_share or mx >= 3) else 'none'
    expected_acc[aid] = (a['account_type'], len(rs), fc, exp)

# ---- Validate composite_request_audit.csv ----
with open('/app/composite_request_audit.csv') as f:
    rows = list(csv.DictReader(f))
if list(rows[0].keys()) != ['request_id','finding']:
    errors.append(f"audit cols: {list(rows[0].keys())}")
if len(rows) != len(audited):
    errors.append(f"audit row count {len(rows)} != {len(audited)}")
got_ids = [r['request_id'] for r in rows]
exp_ids = [r['request_id'] for r in audited]
if got_ids != exp_ids:
    errors.append(f"audit ids/order mismatch:\n got={got_ids}\n exp={exp_ids}")
for r in rows:
    exp = sorted(expected_audit[r['request_id']])
    exp_str = '|'.join(exp) if exp else 'none'
    if r['finding'] != exp_str:
        errors.append(f"audit {r['request_id']}: got '{r['finding']}' exp '{exp_str}'")

# ---- Validate account_summary.csv ----
with open('/app/account_summary.csv') as f:
    arows = list(csv.DictReader(f))
if list(arows[0].keys()) != ['account_id','account_type','request_count','flagged_requests','escalation']:
    errors.append(f"acc cols: {list(arows[0].keys())}")
if len(arows) != 8:
    errors.append(f"acc row count {len(arows)} != 8")
for r in arows:
    aid = r['account_id']
    et, erc, efc, eexp = expected_acc[aid]
    if r['account_type'] != et: errors.append(f"{aid} type {r['account_type']} != {et}")
    if int(r['request_count']) != erc: errors.append(f"{aid} rc {r['request_count']} != {erc}")
    if int(r['flagged_requests']) != efc: errors.append(f"{aid} fc {r['flagged_requests']} != {efc}")
    if r['escalation'] != eexp: errors.append(f"{aid} esc {r['escalation']} != {eexp}")

# ---- Validate results.json ----
with open('/app/results.json') as f:
    j = json.load(f)
exp_j = {
    'request_count': len(audited),
    'account_count': 8,
    'flagged_count': flagged,
    'compliant_count': len(audited)-flagged,
    'finding_total': ftotal,
    'character_count': fcodes['UNLICENSED_CHARACTER_USE'],
    'background_count': fcodes['THIRD_PARTY_BACKGROUND_UNLICENSED'],
    'consent_count': fcodes['MISSING_MINOR_CONSENT'],
    'commercial_count': fcodes['COMMERCIAL_DISTRIBUTION_FLAG'],
    'disclosure_count': fcodes['ALTERATION_DISCLOSURE_MISSING'],
    'escalated_accounts': sum(1 for v in expected_acc.values() if v[3]=='ESCALATION_REQUIRED'),
}
for k,v in exp_j.items():
    if j.get(k) != v:
        errors.append(f"json {k}: {j.get(k)} != {v}")
extra = set(j.keys()) - set(exp_j.keys())
if extra: errors.append(f"json extra keys: {extra}")

if errors:
    print("FAILURES:")
    for e in errors: print(" -", e)
else:
    print("ALL CHECKS PASSED")
    print("Expected JSON:", json.dumps(exp_j))

